async function local(base,p){if(/^(?:[a-z]+:|\/|\\)/i.test(p))throw Error('Nonrelative dependency '+p);const q=path.resolve(root,base,p);if(!q.startsWith(root+path.sep)&&q!==root)throw Error('Path escapes library '+p);await fs.access(q);return q;}
